#include "stdlib/lapack/base/dpbequ.h"
#include "preflight.h"

/**
* Computes band-matrix scaling factors using alternative indexing.
*
* @param uplo         stored triangle
* @param N            number of dense rows and columns
* @param KD           number of stored off-diagonals
* @param AB           read-only compact band matrix
* @param strideAB1    first band dimension stride
* @param strideAB2    second band dimension stride
* @param offsetAB     band starting index
* @param S            output scales or copied diagonal on failure
* @param strideS      scale stride
* @param offsetS      scale starting index
* @param SCOND        mutable ratio output
* @param offsetSCOND  ratio starting index
* @param AMAX         mutable complete diagonal maximum
* @param offsetAMAX   maximum starting index
* @return             INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpbequ_ndarray)( const int uplo, const LAPACK_INT N, const LAPACK_INT KD, const double *AB, const LAPACK_INT strideAB1, const LAPACK_INT strideAB2, const LAPACK_INT offsetAB, double *S, const LAPACK_INT strideS, const LAPACK_INT offsetS, double *SCOND, const LAPACK_INT offsetSCOND, double *AMAX, const LAPACK_INT offsetAMAX ) {
	dpbequ_envelope envelopeAB;
	dpbequ_envelope envelopeS;
	dpbequ_envelope envelopeSC;
	dpbequ_envelope envelopeAM;
	LAPACK_INT height;
	LAPACK_INT delta1;
	LAPACK_INT delta2;
	LAPACK_INT deltaS;
	LAPACK_INT low;
	LAPACK_INT high;
	LAPACK_INT info;

	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return -1;
	if ( N < 0 || N == dpbequ_max() ) return -2;
	if ( KD < 0 || KD == dpbequ_max() ) return -3;
	if ( SCOND == NULL ) return -11;
	if ( !dpbequ_scalar( SCOND, offsetSCOND, &envelopeSC ) ) return -12;
	if ( AMAX == NULL ) return -13;
	if ( !dpbequ_scalar( AMAX, offsetAMAX, &envelopeAM ) ) return -14;
	if ( dpbequ_overlaps( &envelopeSC, &envelopeAM ) ) return -13;
	if ( N == 0 ) {
		SCOND[ offsetSCOND ] = 1.0;
		AMAX[ offsetAMAX ] = 0.0;
		return 0;
	}
	height = KD+1;
	if ( AB == NULL ) return -4;
	if ( !dpbequ_step( height, strideAB1, &delta1 ) ) return -5;
	if ( !dpbequ_step( N, strideAB2, &delta2 ) || !dpbequ_injective( height, N, strideAB1, strideAB2 ) ) return -6;
	if ( !dpbequ_add( delta1 < 0 ? delta1 : 0, delta2 < 0 ? delta2 : 0, &low ) || !dpbequ_add( delta1 > 0 ? delta1 : 0, delta2 > 0 ? delta2 : 0, &high ) || !dpbequ_physical( AB, offsetAB, low, high, &envelopeAB ) ) return -7;
	if ( dpbequ_overlaps( &envelopeAB, &envelopeSC ) || dpbequ_overlaps( &envelopeAB, &envelopeAM ) ) return -4;
	if ( S == NULL ) return -8;
	if ( !dpbequ_step( N, strideS, &deltaS ) ) return -9;
	if ( !dpbequ_physical( S, offsetS, deltaS < 0 ? deltaS : 0, deltaS > 0 ? deltaS : 0, &envelopeS ) ) return -10;
	if ( dpbequ_overlaps( &envelopeS, &envelopeAB ) || dpbequ_overlaps( &envelopeS, &envelopeSC ) || dpbequ_overlaps( &envelopeS, &envelopeAM ) ) return -8;
	info = dpbequ_compute( uplo, N, KD, AB, strideAB1, strideAB2, offsetAB, S, strideS, offsetS, SCOND, offsetSCOND, AMAX, offsetAMAX );
	return info == -1 ? -4 : info;
}
